// «Что после записи» — airиСТая two-column section: текст слева, живое фото врача за работой справа (3:2, rounded),
// ссылка в личный кабинет как основное действие. Own composition, calm rise on enter.
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";
import { srcSetOf, IMAGE_WIDTHS } from "@wizard/ui-kit/v3/headless";

export type AfterSectionProps = {
  heading: string;
  text: string;
  accountHref: string;
  accountLinkText: string;
  photo: string;
  photoAlt: string;
};

const linkClass =
  "inline-flex min-h-11 items-center justify-center rounded-control border-2 border-foreground px-6 text-body font-bold text-foreground transition-colors duration-200 hover:bg-foreground hover:text-background focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

export default function AfterSection({ heading, text, accountHref, accountLinkText, photo, photoAlt }: AfterSectionProps) {
  const reduce = useReducedMotion();
  const rise = reduce
    ? {}
    : {
        initial: { opacity: 0, y: 24 },
        whileInView: { opacity: 1, y: 0 },
        viewport: { once: true, amount: 0.3 },
        transition: { duration: 0.6, ease: "easeOut" as const },
      };

  return (
    <LazyMotion features={domAnimation} strict>
      <section className="bg-card font-sans text-card-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <div className="grid items-center gap-x-10 gap-y-10 md:grid-cols-12">
            <m.div className="order-2 md:order-1 md:col-span-6 lg:col-span-5" {...rise}>
              <div className="max-w-text">
                <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{heading}</h2>
                <p className="mt-5 text-lead text-pretty text-muted-foreground">{text}</p>
                <a
                  href={accountHref}
                  className={`mt-8 ${linkClass}`}
                >
                  {accountLinkText}
                </a>
              </div>
            </m.div>
            <m.figure
              className="order-1 min-w-0 md:order-2 md:col-span-6 lg:col-span-7"
              {...(reduce
                ? {}
                : {
                    initial: { opacity: 0, y: 24 },
                    whileInView: { opacity: 1, y: 0 },
                    viewport: { once: true, amount: 0.2 },
                    transition: { duration: 0.7, ease: "easeOut" as const, delay: 0.1 },
                  })}
            >
              <img
                src={photo}
                srcSet={srcSetOf(photo, IMAGE_WIDTHS)}
                sizes="(min-width: 768px) 55vw, 100vw"
                alt={photoAlt}
                className="aspect-3/2 w-full rounded-lg object-cover"
                loading="lazy"
              />
            </m.figure>
          </div>
        </div>
      </section>
    </LazyMotion>
  );
}

