// First screen of /booking: warm clinic photo, Lora headline on the left,
// CTA scrolls to the form below. On phones the photo follows the text.
import { srcSetOf, useFitWords } from "@wizard/ui-kit/v3/headless";
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

export type HeroBookingProps = {
  heading: string;
  text?: string;
  buttonText: string;
  buttonHref: string;
  photo: string;
  photoAlt: string;
  /** Place of the section in the page source: the build injects it (ui-kit.yaml#wz_id), never the composer. */
  wzId?: string;
};

/** Entrance (rise) — only with the lively motion profile, never with reduced motion. */
function useRise() {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  const on = lively && !reduce;
  return (step: number) =>
    on
      ? {
          initial: { opacity: 0, y: 16 },
          animate: { opacity: 1, y: 0 },
          transition: { duration: 0.6, delay: step * 0.08, ease: [0.23, 1, 0.32, 1] as const },
        }
      : {};
}

export default function HeroBooking({
  heading,
  text,
  buttonText,
  buttonHref,
  photo,
  photoAlt,
  wzId,
}: HeroBookingProps) {
  const rise = useRise();
  const fit = useFitWords<HTMLHeadingElement>(heading);

  return (
    <LazyMotion features={domAnimation}>
      <section data-wz-component="Hero" data-wz-id={wzId} className="bg-background font-sans text-foreground">
        <div className="mx-auto grid w-full max-w-page items-center gap-10 px-gutter py-section lg:grid-cols-12 lg:gap-14">
          {/* Offer: asymmetric grid gives the headline 7 of 12 columns on desktop. */}
          <div className="order-1 min-w-0 lg:col-span-7">
            <m.h1
              ref={fit}
              {...rise(0)}
              className="font-display text-hero font-bold text-balance wrap-break-word hyphens-auto"
            >
              {heading}
            </m.h1>
            {text ? (
              <m.p {...rise(1)} className="mt-6 max-w-text text-lead text-muted-foreground">
                {text}
              </m.p>
            ) : null}
            <m.div {...rise(2)} className="mt-9">
              <a
                href={buttonHref}
                data-testid="wz-hero-primary"
                className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-8 text-center text-body font-bold text-primary-foreground transition-transform duration-200 hover:-translate-y-0.5 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
              >
                {buttonText}
              </a>
            </m.div>
          </div>
          {/* Photo: warm clinic interior, 3:2 on phones, taller crop on desktop. */}
          <m.div {...rise(1)} className="order-2 min-w-0 lg:col-span-5">
            <img
              src={photo}
              srcSet={srcSetOf(photo)}
              sizes="(min-width: 1024px) 42vw, 100vw"
              alt={photoAlt}
              fetchPriority="high"
              className="aspect-3/2 w-full rounded-lg bg-muted object-cover lg:aspect-4/5"
            />
          </m.div>
        </div>
      </section>
    </LazyMotion>
  );
}

